commands.command:
/bin/zsh -lc python - <<'PY'
from more_itertools import numeric_range
r=numeric_range(0.,2.,1e-308)
i=r._get_float_index(1.)
print('lower bound',i)
for d in [-2,-1,0,1,2]:
 n=i+d;print(d,float(n),n*r._step,(n*r._step).hex())
print('division',1./1e-308, (int(1./1e-308)*1e-308).hex())
for target in [0.5,1.,1.5, 1e308*1e-308]:
 try: index=r.index(target); print('target',target,'found',index,'prev',(index-1)*1e-308)
 except Exception as e: print('target',target,'error',e)
PY

