from more_itertools import numeric_range
import math,random
rnd=random.Random(24)
for trial in range(2000):
 start=-rnd.uniform(8e7,1.2e8);step=rnd.uniform(.8e-300,1.2e-300);v=rnd.uniform(1.,1e7)
 r=numeric_range(start,1e8,step)
 try: k=r.index(v)
 except ValueError:continue
 except Exception as e:
  print('FOUND',trial,repr(start),repr(step),repr(v),'error',type(e).__name__,str(e),'old_contains',(v-start)%step==0,'q',divmod(v-start,step)[0]);break
else:print('no errors')
PY

