commands.command:
/bin/zsh -lc python - <<'PY'
import subprocess
from more_itertools import numeric_range
from decimal import Decimal, localcontext
from fractions import Fraction
s=subprocess.check_output(['git','show','2868fe57ce7edcc0ce65a47e9f70cacce1a7c431:more_itertools/more.py'],text=True)
s=s[s.index('class numeric_range(Sequence):'):s.index('\ndef count_cycle(')]
ns={}
from more_itertools import more
exec(s,vars(more).copy(),ns)
old=ns['numeric_range']
cases=[((0.0,1.5e308,10**308),1.3e308), ((0.0,1.0,5e-324),0.5),((Decimal(0),Decimal(10)**30,Decimal(1)),Decimal(10)**29)]
for args,v in cases:
 print('case',str(args)[:120],v)
 for cls in (old,numeric_range):
  r=cls(*args)
  for f in (lambda:v in r,lambda:r.index(v)):
   try:print(cls is old, f())
   except Exception as e:print(cls is old,type(e).__name__,str(e))
PY

